<?php

namespace App\Console\Commands;

use App\Models\IntegrationEndpoint;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\DB;

/**
 * Imports the ESB operation catalog from the generated files in docs/esb/.
 *
 * Those files are a mechanical transcription of the vendor documentation --
 * an OpenAPI description for ESB Core, apiDoc for ESB OMS -- regenerated by
 * docs/esb/generate-catalog.py. Parsing them here keeps one source of truth:
 * the markdown is what a developer reads, and this table is the same content
 * made searchable for operators.
 */
class ImportEndpointCatalogCommand extends Command
{
    protected $signature = 'esb:import-catalog';

    protected $description = 'Import the ESB operation catalog from docs/esb/';

    /**
     * Which generated file maps to which product key.
     */
    private const CATALOGS = [
        'core' => 'docs/esb/esb-core-endpoints.md',
        'oms' => 'docs/esb/esb-oms-endpoints.md',
    ];

    /**
     * Production base URL to base URL family. The catalogs record the
     * production URL declared for each group; this is how a group is mapped
     * onto the families in config/esb.php (ADR-010).
     */
    private const BASE_URL_FAMILIES = [
        'https://services.esb.co.id/core' => 'core',
        'https://services.esb.co.id/voucher' => 'voucher',
        'https://core-api.esb.co.id' => 'fnb_backend',
        'https://esbcore.co.id' => 'pos',
    ];

    public function handle(): int
    {
        $endpoints = [];

        foreach (self::CATALOGS as $product => $relativePath) {
            $path = base_path($relativePath);

            if (! is_file($path)) {
                $this->error("Catalog not found: {$relativePath}. Regenerate it with docs/esb/generate-catalog.py.");

                return self::FAILURE;
            }

            $contents = file_get_contents($path);

            if ($contents === false) {
                $this->error("Could not read {$relativePath}.");

                return self::FAILURE;
            }

            foreach ($this->parse($contents, $product) as $endpoint) {
                $endpoints[$endpoint['code']] = $endpoint;
            }
        }

        if ($endpoints === []) {
            $this->error('No endpoints were parsed. The catalog format may have changed.');

            return self::FAILURE;
        }

        DB::transaction(function () use ($endpoints): void {
            foreach ($endpoints as $endpoint) {
                IntegrationEndpoint::query()->updateOrCreate(
                    ['code' => $endpoint['code']],
                    $endpoint,
                );
            }

            // An operation the vendor withdrew must not linger in a catalog
            // people read to decide what they can call.
            IntegrationEndpoint::query()
                ->whereNotIn('code', array_keys($endpoints))
                ->delete();
        });

        $this->info(sprintf('Imported %d endpoints from %d catalogs.', count($endpoints), count(self::CATALOGS)));

        return self::SUCCESS;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function parse(string $contents, string $product): array
    {
        $endpoints = [];
        $family = null;
        $heading = null;

        foreach (preg_split('/\R/', $contents) ?: [] as $line) {
            $line = trim($line);

            // Each group is a "## Group" section. Its heading is the group
            // name as displayed, for both source formats.
            if (str_starts_with($line, '## ')) {
                $heading = trim(substr($line, 3));
                $family = null;

                continue;
            }

            if (str_starts_with($line, 'Production base URL:')) {
                $family = $this->familyFromBaseUrlLine($line);

                continue;
            }

            $row = $this->parseRow($line);

            if ($row === null) {
                continue;
            }

            [$method, $path, $name, $version, $docsUrl] = $row;

            $code = $this->code($product, $method, $path, $version, $docsUrl);

            if ($code === null || $heading === null) {
                continue;
            }

            $endpoints[] = [
                'code' => $code,
                'product' => $product,
                'group' => $heading,
                'name' => $name,
                'version' => $version,
                'method' => $method,
                'path' => $path,
                // The vendor's narrative "Flow" pages document a process
                // rather than a callable operation, and must not look like
                // something you can invoke.
                'is_operation' => $method !== null && $path !== null,
                'family' => $family ?? 'core',
                'docs_url' => $docsUrl,
            ];
        }

        return $endpoints;
    }

    /**
     * @return array{string|null, string|null, string, string, string}|null
     */
    private function parseRow(string $line): ?array
    {
        $pattern = '/^\|\s*`([^`]*)`\s*\|\s*`(.*?)`\s*\|\s*(.*?)\s*\|\s*`([^`]*)`\s*\|\s*\[docs\]\((\S+)\)\s*\|$/';

        if (! preg_match($pattern, $line, $matches)) {
            return null;
        }

        $method = $matches[1] === '—' ? null : $matches[1];
        $path = $matches[2] === '—' ? null : str_replace('\\|', '|', $matches[2]);

        return [$method, $path, str_replace('\\|', '|', $matches[3]), $matches[4], $matches[5]];
    }

    private function familyFromBaseUrlLine(string $line): ?string
    {
        foreach (self::BASE_URL_FAMILIES as $baseUrl => $family) {
            if (str_contains($line, $baseUrl)) {
                return $family;
            }
        }

        return null;
    }

    /**
     * A stable identity for an operation, from how its source documents it.
     *
     * - apiDoc (`#api-{Group}-{name}`): `{product}:{Group}:{name}@{version}`.
     *   Version is part of the identity, not decoration: the vendor has shipped
     *   two Report/get-sales-information operations that share a group and
     *   name but differ in version, method, and host. Group names use
     *   underscores and never contain a hyphen, so the first hyphen after the
     *   group is the separator.
     * - OpenAPI (`#/paths/...` or `#/operations/...`): `{product}:{METHOD} {path}`.
     *   Method and path are unique in an OpenAPI document; the tag and the
     *   document version are not part of it, so re-tagging or a version bump
     *   upstream does not look like every operation being replaced.
     */
    private function code(string $product, ?string $method, ?string $path, string $version, string $docsUrl): ?string
    {
        if (preg_match('/#api-([A-Za-z0-9_]+)-(.+)$/', $docsUrl, $matches)) {
            return $product.':'.$matches[1].':'.$matches[2].'@'.$version;
        }

        if (preg_match('~#/(paths|operations)/~', $docsUrl) && $method !== null && $path !== null) {
            return $product.':'.$method.' '.$path;
        }

        return null;
    }
}
